select p.name, p.contract_amount, count(distinct b.id) as lines, coalesce(sum(b.billed),0) as billed, (select count(*) from pay_apps x where x.project_id=p.id) as payapps, (select count(*) from change_orders x where x.project_id=p.id) as cos from projects p left join budget_lines b on b.project_id=p.id group by p.id order by p.name;
