insert into change_orders (project_id, code, title, amount, description, status, sent_date, decided_date) values ((select id from projects where name = '354 Arno Way'), 'CO-01', 'Partial demolition and removal of existing patio slab and stone pavers', 17876.0, 'At your request, partial demolition and removal of the existing patio slab and the stone paver finish installed over it, which was not included in the Construction Agreement dated 7/18/26. Approximately 700 SF of 3/4" stone pavers in a mortar bed over a 10" concrete slab. Includes sawcutting a clean edge at the work to remain, protection of adjacent finishes, machine demolition, removal of reinforcing, dust control, rough grading of the exposed subgrade, and hauling to a permitted recycling facility ($12,188 demolition + $5,688 disposal). Does not include new concrete, pavers or hardscape in the removal area, paver salvage, structural work, utility relocation, or hazardous material handling. The 8% management fee applies and is billed separately.', 'approved', '2026-09-02', '2026-09-02');
insert into change_orders (project_id, code, title, amount, description, status, sent_date, decided_date) values ((select id from projects where name = '354 Arno Way'), 'CO-02', '2-ft garden wall above the second retaining wall and swale, 100 LF', 23788.0, 'Construction of a 2-foot garden (retaining) wall above the second retaining wall and swale, approximately 100 linear feet. $13,788 billed on pay application 2.', 'pending', '2026-09-30', NULL);
insert into change_orders (project_id, code, title, amount, description, status, sent_date, decided_date) values ((select id from projects where name = '354 Arno Way'), 'CO-03', 'Soil replacement and landscape soil removal (draft, under review)', 30364.0, 'Engineered fill in the CO-01 patio excavation (approx. 33 CY); excavation and export of 3 ft of soil over approx. 707 SF of landscape area (approx. 102 tons); and import of approx. 95 CY of screened topsoil. The 8% management fee is billed separately.', 'pending', '2026-09-02', NULL);
