insert into change_orders (project_id, code, title, amount, description, status, sent_date, decided_date) values ((select id from projects where name = '424 Almar Ave'), 'CO-001', 'Mold remediation — bedroom wall/ceiling, insulation, shear plywood, flooring (labor)', 3770.92, 'Remediation of an additional ~72 SF section of the bedroom wall and a larger ceiling section due to further mold, with new insulation on the NW wall (R-30/R-19), new drywall taped and painted, re-routed exterior light circuit with new junction box, fire blocking and 88 SF of new shear plywood, waterproofing of the exterior plywood patches, and labor-only reinstallation of ~47 SF of client-supplied hardwood floor.', 'pending', '2024-08-20', NULL);
