insert into change_orders (project_id, code, title, amount, description, status, sent_date, decided_date) values ((select id from projects where name = '424 Almar Ave'), 'MH-CO-001', 'Main House General CO 001 — seal exterior openings with plastic', 3688.0, 'Sealing all essential exterior openings and penetrations (windows, doors, ducts, HVAC) with 6-mil plastic on 2x2 frames anchored into the stucco, with patching of screw penetrations after removal; approximately 4-5 days with two team members, labor and material included.', 'pending', '2025-03-10', NULL);
insert into change_orders (project_id, code, title, amount, description, status, sent_date, decided_date) values ((select id from projects where name = '424 Almar Ave'), 'CO-004', 'Mold remediation — hallway bath and guest bath framing/drywall', 3588.0, 'Mold treatment in the guest and hallway bathrooms, replacement of molded 2x4 framing and sill plates (pressure-treated), and cut-out and replacement of ~125 SF of affected drywall in the hallway and guest bedroom including mud, tape and finish.', 'pending', '2025-07-18', NULL);
