insert into change_orders (project_id, code, title, amount, description, status, sent_date, decided_date) values ((select id from projects where name = '424 Almar Ave'), 'CO-006', 'Phase 3 Remediation — contaminated soil removal (min. 6 in.)', 24788.0, 'Removal of a minimum of 6 inches of fire-contaminated soil (~2,737 SF, approx. 51 CY minimum) at all designated planters, backyard patio and side pathway per LADBS/EPA recommendation, with containment, excavation, covered transport and disposal at a certified facility, plus a before/after report. Includes excavation, hauling, dump fees and the hazardous-overage fee. Tree and vegetation removal is excluded and priced separately.', 'pending', '2025-09-29', NULL);
