insert into change_orders (project_id, code, title, amount, description, status, sent_date, decided_date) values ((select id from projects where name = '16026 W Junaluska Way'), 'CO-01', 'Interior scope — kitchen cabinet wall/soffit removal, reframe & drywall, refinish kitchen and upstairs casework', 21976.0, 'At your request, the built-in cabinetry, its housing wall and soffit, and the pop-out wall in the kitchen are removed; the areas are reframed flush, drywalled to a Level 5 finish and painted, with existing kitchen lighting relocated. The existing kitchen cabinetry (approx. 36 LF) is stripped and refinished in place with a new flush toe kick, and the upstairs office casework (approx. 19 LF) is stripped and refinished. Structural work, new cabinetry or hardware, countertops, new lighting lines and hazardous-material abatement are excluded. Estimated 25 business days.', 'pending', '2026-08-17', NULL);
insert into change_orders (project_id, code, title, amount, description, status, sent_date, decided_date) values ((select id from projects where name = '16026 W Junaluska Way'), 'CO-02', 'Cabinetry refinishing, kitchen and second floor (insurance claim 004296826-801)', 18101.0, 'Following wildfire exposure, the exposed natural-wood kitchen cabinetry (approx. 36 LF) and the second-floor office built-ins (approx. 19 LF) are stripped, sanded and refinished in place under full containment with HEPA filtration to remove ash and soot held in the finish and wood grain. New hardware, cabinet boxes, countertops, lighting and wall painting are excluded. Estimated 20 business days.', 'pending', '2026-09-22', NULL);
