insert into change_orders (project_id, code, title, amount, description, status, sent_date, decided_date) values ((select id from projects where name = '9546 Monte Mar Dr'), 'CO-06', 'Horizontal cedar fence on CMU walls, entry-window siding, garage-wall transition', 14895.0, 'Installs 24-inch-high horizontal cedar fencing on new 4x4 posts anchored to the top of the existing CMU walls at the west side (33 LF) and south (58 LF), primed and painted in a designer-selected color; replaces approx. 36 SF of rotted siding at the entry window with Hardie lap siding and new weep screed; removes corroded metal at the garage plate line and installs new weep screed, waterproofing, flashing and drainage board over 18 LF; and installs approx. 54 SF of new Hardie siding at the garage wall. The existing CMU wall is noted as compromised and is not warranted; structural work and permits are excluded.', 'pending', '2026-07-26', NULL);
